begin;
create table public.projects (id text not null, user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), status text, priority text, "startDate" text, date text, time text, notes text, name text, "clientName" text, "clientContact" text, "projectValue" numeric, "clientAmountReceived" numeric, "amountPending" numeric, "dueDate" text, description text, "createdAt" text, "updatedAt" text, "completedDate" text, primary key(user_id,id)); alter table public.projects enable row level security; create policy owner_select on public.projects for select to authenticated using (auth.uid()=user_id); create policy owner_insert on public.projects for insert to authenticated with check (auth.uid()=user_id); create policy owner_update on public.projects for update to authenticated using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy owner_delete on public.projects for delete to authenticated using (auth.uid()=user_id); grant select,insert,update,delete on public.projects to authenticated; revoke all on public.projects from anon;
create table public.tasks (id text not null, user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), status text, priority text, "startDate" text, date text, time text, notes text, "projectId" text, name text, description text, "assignedPersonId" text, "jobCost" numeric, "amountPaid" numeric, "amountPending" numeric, "dueDate" text, "completedDate" text, "order" numeric, primary key(user_id,id)); alter table public.tasks enable row level security; create policy owner_select on public.tasks for select to authenticated using (auth.uid()=user_id); create policy owner_insert on public.tasks for insert to authenticated with check (auth.uid()=user_id); create policy owner_update on public.tasks for update to authenticated using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy owner_delete on public.tasks for delete to authenticated using (auth.uid()=user_id); grant select,insert,update,delete on public.tasks to authenticated; revoke all on public.tasks from anon;
create table public.people (id text not null, user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), status text, priority text, "startDate" text, date text, time text, notes text, name text, role text, "salaryOrJobCost" numeric, contact text, primary key(user_id,id)); alter table public.people enable row level security; create policy owner_select on public.people for select to authenticated using (auth.uid()=user_id); create policy owner_insert on public.people for insert to authenticated with check (auth.uid()=user_id); create policy owner_update on public.people for update to authenticated using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy owner_delete on public.people for delete to authenticated using (auth.uid()=user_id); grant select,insert,update,delete on public.people to authenticated; revoke all on public.people from anon;
create table public.purchases (id text not null, user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), status text, priority text, "startDate" text, date text, time text, notes text, "projectId" text, "itemName" text, vendor text, "totalAmount" numeric, "amountPaid" numeric, "amountPending" numeric, primary key(user_id,id)); alter table public.purchases enable row level security; create policy owner_select on public.purchases for select to authenticated using (auth.uid()=user_id); create policy owner_insert on public.purchases for insert to authenticated with check (auth.uid()=user_id); create policy owner_update on public.purchases for update to authenticated using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy owner_delete on public.purchases for delete to authenticated using (auth.uid()=user_id); grant select,insert,update,delete on public.purchases to authenticated; revoke all on public.purchases from anon;
create table public.reminders (id text not null, user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), status text, priority text, "startDate" text, date text, time text, notes text, title text, description text, "projectId" text, completed boolean, primary key(user_id,id)); alter table public.reminders enable row level security; create policy owner_select on public.reminders for select to authenticated using (auth.uid()=user_id); create policy owner_insert on public.reminders for insert to authenticated with check (auth.uid()=user_id); create policy owner_update on public.reminders for update to authenticated using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy owner_delete on public.reminders for delete to authenticated using (auth.uid()=user_id); grant select,insert,update,delete on public.reminders to authenticated; revoke all on public.reminders from anon;
create function public.touch_jobflow_row() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end $$;
create trigger touch_updated_at before update on public.projects for each row execute function public.touch_jobflow_row();
create trigger touch_updated_at before update on public.tasks for each row execute function public.touch_jobflow_row();
create trigger touch_updated_at before update on public.people for each row execute function public.touch_jobflow_row();
create trigger touch_updated_at before update on public.purchases for each row execute function public.touch_jobflow_row();
create trigger touch_updated_at before update on public.reminders for each row execute function public.touch_jobflow_row();
create function public.save_jobflow_workspace(workspace jsonb) returns void language plpgsql security invoker set search_path=public as $$ declare uid uuid:=auth.uid(); begin if uid is null then raise exception 'Authentication required'; end if;
if jsonb_typeof(workspace->'projects') is distinct from 'array' then raise exception 'Invalid projects collection'; end if; delete from public.projects where user_id=uid; insert into public.projects select (jsonb_populate_record(null::public.projects, value || jsonb_build_object('user_id',uid,'created_at',coalesce(value->>'created_at',now()::text),'updated_at',now()))).* from jsonb_array_elements(workspace->'projects');
if jsonb_typeof(workspace->'tasks') is distinct from 'array' then raise exception 'Invalid tasks collection'; end if; delete from public.tasks where user_id=uid; insert into public.tasks select (jsonb_populate_record(null::public.tasks, value || jsonb_build_object('user_id',uid,'created_at',coalesce(value->>'created_at',now()::text),'updated_at',now()))).* from jsonb_array_elements(workspace->'tasks');
if jsonb_typeof(workspace->'people') is distinct from 'array' then raise exception 'Invalid people collection'; end if; delete from public.people where user_id=uid; insert into public.people select (jsonb_populate_record(null::public.people, value || jsonb_build_object('user_id',uid,'created_at',coalesce(value->>'created_at',now()::text),'updated_at',now()))).* from jsonb_array_elements(workspace->'people');
if jsonb_typeof(workspace->'purchases') is distinct from 'array' then raise exception 'Invalid purchases collection'; end if; delete from public.purchases where user_id=uid; insert into public.purchases select (jsonb_populate_record(null::public.purchases, value || jsonb_build_object('user_id',uid,'created_at',coalesce(value->>'created_at',now()::text),'updated_at',now()))).* from jsonb_array_elements(workspace->'purchases');
if jsonb_typeof(workspace->'reminders') is distinct from 'array' then raise exception 'Invalid reminders collection'; end if; delete from public.reminders where user_id=uid; insert into public.reminders select (jsonb_populate_record(null::public.reminders, value || jsonb_build_object('user_id',uid,'created_at',coalesce(value->>'created_at',now()::text),'updated_at',now()))).* from jsonb_array_elements(workspace->'reminders');
end $$; revoke all on function public.save_jobflow_workspace(jsonb) from public,anon; grant execute on function public.save_jobflow_workspace(jsonb) to authenticated; commit;
